mapper.select:
SELECT * FROM (
    SELECT t.*, ROWNUM rn FROM (
        SELECT 
        FROM SYS_USER u LEFT JOIN SYS_ROLE r ON u.ROLE_ID = r.ROLE_ID
        WHERE u.IS_DELETED = 0

            AND (u.USERNAME LIKE '%' || #{keyword} || '%' OR u.REAL_NAME LIKE '%' || #{keyword} || '%')


            AND u.STATUS = #{status}

        ORDER BY u.USER_ID DESC
    ) t WHERE ROWNUM <= #{offset} + #{limit}
) WHERE rn > #{offset}

SELECT COUNT(1) FROM SYS_USER u WHERE u.IS_DELETED = 0

    AND (u.USERNAME LIKE '%' || #{keyword} || '%' OR u.REAL_NAME LIKE '%' || #{keyword} || '%')


    AND u.STATUS = #{status}
